// @FIGURE_CODE_BEGIN
(function () {
  var SEA = '#5ff7e0', LAND = '#c2830c', LAND_EDGE = '#8a5407',
      CLIFF = '#7a3c08', CLIFF_EDGE = '#5a2b05', GREY = '#bdbdbd';

  var W = 1000, H = 450;
  var horizonY = 196, yWater = 360, eyeX = 215;
  var PHYS_ALPHA = 52 * Math.PI / 180;

  window.figState = { mode: 'single', h: 40, t: 80, d: 400 };
  var S = window.figState;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  var root = draw.group();

  /* ---------- helpers ---------- */
  function pstr(arr) { return arr.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '); }

  function label(str, x, y, size, color, anchor) {
    var t = root.plain(str);
    t.font({ family: 'Georgia,"Times New Roman",serif', size: size, anchor: anchor || 'middle' });
    t.fill(color || '#000');
    t.attr({ x: x, y: y, 'dominant-baseline': 'central', 'paint-order': 'stroke',
             stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
    return t;
  }

  function txt(str, x, y, size, color, bold, serif) {
    var t = root.plain(str);
    t.font({ family: serif ? 'Georgia,"Times New Roman",serif' : 'Helvetica,Arial,sans-serif',
             size: size, anchor: 'start', weight: bold ? 'bold' : 'normal' });
    t.fill(color || '#111');
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    return t;
  }

  function angSpan(a1, a2) {
    var d = a2 - a1;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    return { a1: a1, a2: a1 + d, mid: a1 + d / 2 };
  }

  function arc(cx, cy, r, a1, a2) {
    var pts = [], n = 36;
    for (var i = 0; i <= n; i++) {
      var a = a1 + (a2 - a1) * i / n;
      pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
    }
    return root.polyline(pstr(pts)).fill('none').stroke({ color: '#000', width: 2.2, linecap: 'round' });
  }

  function rightAngle(px, py, u1, u2, s) {
    var p = [[px, py], [px + u1[0] * s, py + u1[1] * s],
             [px + (u1[0] + u2[0]) * s, py + (u1[1] + u2[1]) * s],
             [px + u2[0] * s, py + u2[1] * s]];
    return root.polygon(pstr(p)).fill(GREY).stroke({ color: '#000', width: 2 });
  }

  function norm(v) { var l = Math.sqrt(v[0] * v[0] + v[1] * v[1]) || 1; return [v[0] / l, v[1] / l]; }

  function attach(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }

  function hitLine(x1, y1, x2, y2) {
    return root.line(x1, y1, x2, y2).stroke({ color: '#000', width: 20, opacity: 0.001 });
  }

  /* ---------- mappings (schematic, monotone) ---------- */
  function hToPix(h) { return 340 * h / (h + 25); }
  function dToX(d) { return 420 + 502 * Math.pow(Math.max(0, d - 50) / 1150, 0.38); }
  function xToD(x) {
    var f = (x - 420) / 502; f = Math.max(0, Math.min(1, f));
    return 50 + 1150 * Math.pow(f, 1 / 0.38);
  }

  /* ---------- sailboat ---------- */
  var dragging = false;
  function boatGroup(x, yBase, sc) {
    var g = root.group();
    g.path('M -38 0 Q -20 -7 0 -7 Q 22 -7 40 0 Q 26 16 0 17 Q -26 16 -38 0 Z')
      .fill('#fff').stroke({ color: '#000', width: 3.4, linejoin: 'round' });
    g.line(-31, 3, 35, 3).stroke({ color: '#000', width: 2.4 });
    g.line(0, 4, 0, -80).stroke({ color: '#000', width: 3.4 });
    g.path('M -1 -78 Q -22 -40 -36 -11 L -1 -11 Z')
      .fill('#fff').stroke({ color: '#000', width: 3.2, linejoin: 'round' });
    g.path('M 2 -72 L 2 -11 L 33 -11 Z')
      .fill('#fff').stroke({ color: '#000', width: 3.2, linejoin: 'round' });
    g.attr('transform', 'translate(' + x + ',' + yBase + ') scale(' + sc + ')');
    attach(g, 'Boat — drag sideways to change its true distance d',
      'The target',
      'The boat is the unknown. Its image position alone carries no distance information: you only recover d by combining a known length in the scene (the observer height h, or the baseline t) with measured angles.');
    g.on('mousedown', function (e) { dragging = true; e.preventDefault(); });
    return g;
  }

  function observer(x, y, tip) {
    var c = root.circle(34).center(x, y).fill('#fff').stroke({ color: '#000', width: 4.5 });
    attach(c, tip, 'The observer',
      'The observer measures only angles. Angles alone never give distance — they must be anchored to a known length: the height of the eye above the water, or the separation from a second observer.');
    return c;
  }

  /* ---------- land ---------- */
  function drawLandSingle(ey) {
    var ochre = [[-14, H + 12], [-14, 320], [40, 308], [92, 300], [140, 306], [192, 300],
      [244, 308], [298, 322], [346, 342], [392, 356], [436, 366], [478, 380],
      [516, 398], [548, 424], [566, H + 12]];
    root.polygon(pstr(ochre)).fill(LAND).stroke({ color: LAND_EDGE, width: 5, linejoin: 'round' });

    var base = yWater + 8, pts = [[52, base]], i, s, n = 5;
    for (i = 1; i <= n; i++) {
      s = i / n;
      pts.push([52 + (eyeX - 52) * Math.pow(s, 0.85) + (i % 2 ? 6 : -6),
                base + (ey + 10 - base) * Math.pow(s, 1.3)]);
    }
    for (i = 1; i <= n; i++) {
      s = i / n;
      pts.push([eyeX + (322 - eyeX) * Math.pow(s, 0.95) + (i % 2 ? -5 : 5),
                (ey + 10) + (base + 2 - (ey + 10)) * Math.pow(s, 0.62)]);
    }
    root.polygon(pstr(pts)).fill(CLIFF).stroke({ color: CLIFF_EDGE, width: 6, linejoin: 'round' });
  }

  function drawLandTwo() {
    var pts = [[-14, H + 12], [-14, 198], [66, 202], [124, 206], [172, 212], [206, 224],
      [240, 240], [268, 262], [296, 283], [322, 308], [348, 331], [372, 354],
      [398, 379], [420, 406], [438, H + 12]];
    root.polygon(pstr(pts)).fill(LAND).stroke({ color: LAND_EDGE, width: 5, linejoin: 'round' });
  }

  /* ---------- single observer scene ---------- */
  function drawSingle() {
    var hp = hToPix(S.h), ey = yWater - hp;
    var xB = dToX(S.d), yB = yWater, LW = 3;

    drawLandSingle(ey);

    root.line(eyeX, ey, 600, ey).stroke({ color: '#000', width: LW });
    root.line(eyeX, ey, xB, yB).stroke({ color: '#000', width: LW });
    root.line(eyeX, ey, eyeX, yWater).stroke({ color: '#000', width: LW });
    root.line(eyeX, yWater, xB, yWater).stroke({ color: '#000', width: LW });
    rightAngle(eyeX, yWater, [0, -1], [1, 0], 17);

    attach(hitLine(eyeX + 40, ey, 600, ey),
      'Horizontal line of sight to the horizon — the angle reference',
      'The horizon ray',
      'Because the sea is flat, the observer has a free horizontal reference: the line of sight to the horizon. The depression angle α is measured down from it.');
    attach(hitLine(eyeX, ey + 20, eyeX, yWater),
      'h = known eye height above the water — the baseline of this method',
      'Height is the baseline',
      'The eye height h is the known length. Together with the right angle at the water plane and the measured angle α, it closes the triangle: d = h / tan α.');
    attach(hitLine(eyeX + 20, yWater, xB - 30, yWater),
      'd = the unknown horizontal distance to the boat',
      'The unknown distance',
      'The horizontal leg of the right triangle is the quantity we want. It is never measured directly — it is inferred from h and α.');

    var aB = Math.atan2(yB - ey, xB - eyeX);
    var arc1 = arc(eyeX, ey, 80, 0, aB);
    attach(arc1, 'α = depression angle at the eye (atan(h/d))', 'The depression angle',
      'α is the angle between the horizon ray and the sight ray to the boat. As the boat recedes α shrinks toward zero, so a small angular error produces a huge distance error.');
    label('α', eyeX + 108 * Math.cos(aB / 2), ey + 108 * Math.sin(aB / 2), 30);

    var aE = Math.atan2(ey - yB, eyeX - xB);
    var sp = angSpan(Math.PI, aE < 0 ? aE + 2 * Math.PI : aE);
    var arc2 = arc(xB, yB, 70, sp.a1, sp.a2);
    attach(arc2, 'the same α reappears at the boat (alternate interior angles)',
      'Alternate interior angles',
      'The horizon ray and the water plane are parallel, so the sight line cuts them at equal angles. The angle at the boat equals α — this is what lets the right triangle be solved.');
    label('α', xB + 96 * Math.cos(sp.mid), yB + 96 * Math.sin(sp.mid), 30);

    label('h', eyeX - 32, (ey + yWater) / 2, 30);
    label('d?', eyeX + 0.36 * (xB - eyeX), yWater - 24, 30);

    boatGroup(xB, yB, 0.95);
    observer(eyeX, ey, 'Observer, height h above the water');
  }

  /* ---------- two observer scene ---------- */
  function drawTwo() {
    drawLandTwo();

    var A = [210, 225], u = [0.72, 0.694], LW = 3;
    var L = 281 * Math.sqrt(S.t / 200);
    var B = [A[0] + u[0] * L, A[1] + u[1] * L];
    var xB = dToX(S.d), P = [xB, 288];

    root.line(A[0], A[1], B[0], B[1]).stroke({ color: '#000', width: LW });
    root.line(A[0], A[1], P[0], P[1]).stroke({ color: '#000', width: LW });
    root.line(B[0], B[1], P[0], P[1]).stroke({ color: '#000', width: LW });

    var dir = norm([P[0] - A[0], P[1] - A[1]]);
    var proj = (B[0] - A[0]) * dir[0] + (B[1] - A[1]) * dir[1];
    var F = [A[0] + dir[0] * proj, A[1] + dir[1] * proj];
    root.line(B[0], B[1], F[0], F[1]).stroke({ color: '#000', width: 2 });
    rightAngle(F[0], F[1], [-dir[0], -dir[1]], norm([B[0] - F[0], B[1] - F[1]]), 15);

    attach(hitLine(A[0] + 22 * u[0], A[1] + 22 * u[1], B[0] - 22 * u[0], B[1] - 22 * u[1]),
      't = known separation between the observers — the baseline',
      'The baseline t',
      'Here the known length is the separation between two observers. Its component perpendicular to the line of sight (the short segment with the right-angle mark) is what actually sets the precision of the estimate.');
    attach(hitLine(A[0] + 40, A[1] + 5, P[0] - 45, P[1] - 4),
      'd = distance from the upper observer to the boat (unknown)',
      'The unknown distance',
      'With t known and both angles measured, the law of sines gives d = t · sin β / sin(α + β). No height and no horizon are needed.');

    var a1 = Math.atan2(u[1], u[0]);
    var a2 = Math.atan2(P[1] - A[1], P[0] - A[0]);
    var spA = angSpan(a2, a1);
    attach(arc(A[0], A[1], 58, spA.a1, spA.a2),
      'α — angle at the upper observer, between baseline and sight ray',
      'Angle α', 'The upper observer measures the angle between the baseline to the partner and the sight ray to the boat.');
    label('α', A[0] + 88 * Math.cos(spA.mid), A[1] + 88 * Math.sin(spA.mid), 30);

    var b1 = Math.atan2(A[1] - B[1], A[0] - B[0]);
    var b2 = Math.atan2(P[1] - B[1], P[0] - B[0]);
    var spB = angSpan(b1, b2);
    attach(arc(B[0], B[1], 50, spB.a1, spB.a2),
      'β — angle at the lower observer, between baseline and sight ray',
      'Angle β', 'The second observer measures its own angle to the same boat. The two angles plus the baseline fix the third vertex of the triangle.');
    label('β', B[0] + 74 * Math.cos(spB.mid), B[1] + 74 * Math.sin(spB.mid), 30);

    var xm = A[0] + 0.52 * (P[0] - A[0]);
    var yUp = A[1] + (xm - A[0]) / (P[0] - A[0]) * (P[1] - A[1]);
    var yLo = B[1] + (xm - B[0]) / (P[0] - B[0]) * (P[1] - B[1]);
    label('d?', xm, (yUp + yLo) / 2, 30);

    var mid = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2];
    label('t', mid[0] - 0.694 * 30, mid[1] + 0.72 * 30, 30);

    boatGroup(P[0], P[1], 0.95);
    observer(A[0], A[1], 'Upper observer — measures α');
    observer(B[0], B[1], 'Lower observer — measures β');
  }

  /* ---------- read-out ---------- */
  function drawReadout() {
    var lines = [], warn = false, dc, a, aD;
    if (S.mode === 'single') {
      a = Math.atan(S.h / S.d); aD = a * 180 / Math.PI; dc = S.h / Math.tan(a);
      warn = aD < 2.5;
      lines.push({ t: 'Single observer — height + horizon', s: 15, b: true });
      lines.push({ t: 'd = h / tan α', s: 18, serif: true });
      lines.push({ t: 'h = ' + S.h + ' m      α = ' + aD.toFixed(2) + '°', s: 14 });
      lines.push({ t: '\u21d2 d = ' + Math.round(dc) + ' m', s: 16, b: true, c: warn ? '#c00000' : '#000' });
    } else {
      var al = PHYS_ALPHA;
      var dx = S.d * Math.cos(al) - S.t, dy = S.d * Math.sin(al);
      var phi = Math.atan2(dy, dx), be = Math.PI - phi, ga = phi - al;
      dc = S.t * Math.sin(be) / Math.sin(al + be);
      warn = ga * 180 / Math.PI < 3;
      lines.push({ t: 'Two observers — triangulation', s: 15, b: true });
      lines.push({ t: 'd = t · sin β / sin(α + β)', s: 18, serif: true });
      lines.push({ t: 't = ' + S.t + ' m      α = ' + (al * 180 / Math.PI).toFixed(1) +
                     '°      β = ' + (be * 180 / Math.PI).toFixed(1) + '°', s: 14 });
      lines.push({ t: 'angle at boat  γ = 180° − α − β = ' + (ga * 180 / Math.PI).toFixed(1) + '°',
                   s: 14, c: warn ? '#c00000' : '#333' });
      lines.push({ t: '\u21d2 d = ' + Math.round(dc) + ' m', s: 16, b: true, c: warn ? '#c00000' : '#000' });
    }
    if (warn) lines.push({ t: '\u26a0 tiny angle — d poorly determined', s: 13, c: '#c00000' });

    var x0 = 612, y0 = 12, w = 376, hh = 16 + lines.length * 23;
    var box = root.rect(w, hh).move(x0, y0).radius(6).fill('#ffffff').opacity(0.93)
      .stroke({ color: warn ? '#c00000' : '#555', width: warn ? 2.5 : 1.5 });
    attach(box, 'Known length, measured angles, and the inferred distance',
      'Reading the geometry',
      'The read-out is exact: the angles follow from the true h, t and d, and the formula returns d. When the baseline is small compared with the distance the enclosed angle collapses and the inferred d becomes extremely sensitive to angular error — the same failure mode as small-baseline stereo vision.');

    var y = y0 + 22;
    for (var i = 0; i < lines.length; i++) {
      txt(lines[i].t, x0 + 14, y, lines[i].s, lines[i].c || '#111', lines[i].b, lines[i].serif);
      y += 23;
    }
  }

  /* ---------- render ---------- */
  function render() {
    root.clear();
    root.rect(W, H).move(0, 0).fill('#ffffff');
    root.rect(W, H - horizonY).move(0, horizonY).fill(SEA);
    root.line(0, horizonY, W, horizonY).stroke({ color: '#000', width: 5 });
    if (S.mode === 'single') drawSingle(); else drawTwo();
    drawReadout();
    root.rect(W - 6, H - 6).move(3, 3).fill('none').stroke({ color: '#000', width: 6 });
  }
  window.figRender = render;

  /* ---------- drag ---------- */
  function svgPoint(e) {
    var r = draw.node.getBoundingClientRect();
    var s = Math.min(r.width / W, r.height / H);
    var ox = (r.width - W * s) / 2, oy = (r.height - H * s) / 2;
    return { x: (e.clientX - r.left - ox) / s, y: (e.clientY - r.top - oy) / s };
  }
  window.addEventListener('mousemove', function (e) {
    if (!dragging) return;
    var p = svgPoint(e);
    var nd = Math.max(50, Math.min(1200, Math.round(xToD(p.x) / 10) * 10));
    if (nd !== S.d) { S.d = nd; window.figSetSlider('boatDistance', nd); render(); }
  });
  window.addEventListener('mouseup', function () { dragging = false; });

  render();
  window.__markRendered();
})();

/* ---------- UI plumbing ---------- */
function figSetSlider(id, v) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = v;
  if (out) out.value = v;
}
window.figSetSlider = figSetSlider;

function figSyncUI() {
  var single = window.figState.mode === 'single';
  var hRow = document.getElementById('hRow'), tRow = document.getElementById('tRow');
  if (hRow) hRow.style.opacity = single ? '1' : '0.38';
  if (tRow) tRow.style.opacity = single ? '0.38' : '1';
}

function update_observerHeight(v) { window.figState.h = v; window.figRender(); }
function update_observerSeparation(v) { window.figState.t = v; window.figRender(); }
function update_boatDistance(v) { window.figState.d = v; window.figRender(); }
function toggle_methodToggle(on) { window.figState.mode = on ? 'two' : 'single'; figSyncUI(); window.figRender(); }

/* ---------- demo steps ---------- */
var demoSteps = [
  { title: 'The unknown: how far is the boat?',
    narration: 'A boat floats on a flat sea, its distance d unknown. Nothing in the picture alone tells you how far it is — you need a known length somewhere in the scene.',
    state: { methodToggle: 'Single observer (height + horizon)', observerHeight: 40, boatDistance: 400 } },
  { title: 'Height plus horizon gives one baseline',
    narration: 'The observer\'s eye height h above the water is the known length, and the horizon supplies a perfectly horizontal reference ray. The depression angle α between horizon and boat closes the right triangle: d = h / tan α.',
    state: { methodToggle: 'Single observer (height + horizon)', observerHeight: 40, boatDistance: 400 } },
  { title: 'Raise the observer',
    narration: 'Climb the cliff and α opens up for the same boat. A taller vantage point measures a larger, more reliable angle — which is why lookouts sit high on the mast.',
    state: { methodToggle: 'Single observer (height + horizon)', observerHeight: 110, boatDistance: 400 } },
  { title: 'Distant boats break the cue',
    narration: 'Push the boat far out and α collapses toward zero; a small angular error now produces a huge distance error. Geometric depth estimation degrades with range.',
    state: { methodToggle: 'Single observer (height + horizon)', observerHeight: 40, boatDistance: 1100 } },
  { title: 'Switch to two observers',
    narration: 'Now the known length is the baseline t between two observers on the shore. Each measures an angle to the boat, and the law of sines fixes the third vertex of the triangle — no horizon or height needed.',
    state: { methodToggle: 'Two observers (triangulation)', observerSeparation: 80, boatDistance: 400 } },
  { title: 'Shrink the baseline',
    narration: 'Bring the observers close together and the two sight rays become nearly parallel: the triangle is almost degenerate and d is poorly determined. This is exactly the small-baseline problem in stereo vision.',
    state: { methodToggle: 'Two observers (triangulation)', observerSeparation: 10, boatDistance: 400 } },
  { title: 'Widen the baseline',
    narration: 'Separate the observers and the angles at the boat differ strongly, pinning the distance down precisely. Baseline length trades against how far away you can reliably see depth.',
    state: { methodToggle: 'Two observers (triangulation)', observerSeparation: 190, boatDistance: 400 } }
];
var demoIdx = 0;

function applyDemoStep(i) {
  demoIdx = (i + demoSteps.length) % demoSteps.length;
  var st = demoSteps[demoIdx], s = st.state;
  if (s.methodToggle !== undefined) {
    var two = /^Two/.test(s.methodToggle);
    var cb = document.getElementById('methodToggleInput');
    if (cb) cb.checked = two;
    window.figState.mode = two ? 'two' : 'single';
  }
  if (s.observerHeight !== undefined) { window.figState.h = s.observerHeight; figSetSlider('observerHeight', s.observerHeight); }
  if (s.observerSeparation !== undefined) { window.figState.t = s.observerSeparation; figSetSlider('observerSeparation', s.observerSeparation); }
  if (s.boatDistance !== undefined) { window.figState.d = s.boatDistance; figSetSlider('boatDistance', s.boatDistance); }
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (demoIdx + 1) + ' / ' + demoSteps.length;
  figSyncUI();
  window.figRender();
}
function nextStep() { applyDemoStep(demoIdx + 1); }
function prevStep() { applyDemoStep(demoIdx - 1); }

applyDemoStep(0);
// @FIGURE_CODE_END

