  function T(g, str, x, y, size, o) {
    o = o || {};
    var t = g.plain(str);
    t.font({
      family: o.sans ? 'Helvetica,Arial,sans-serif' : 'Georgia,"Times New Roman",serif',
      size: size, anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal', weight: o.bold ? 'bold' : 'normal'
    });
    t.fill(o.color || INK);
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.hw || 6, 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function attach(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function hitLine(g, x1, y1, x2, y2) {
    return g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 20, opacity: 0.001 });
  }

  function angSpan(a1, a2) {
    var d = a2 - a1;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    return { a1: a1, a2: a1 + d, mid: a1 + d / 2, w: Math.abs(d) };
  }

  function arcEl(g, cx, cy, r, a1, a2, w) {
    var pts = [], n = 40, i, a;
    for (i = 0; i <= n; i++) {
      a = a1 + (a2 - a1) * i / n;
      pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
    }
    g.polyline(pstr(pts)).fill('none').stroke({ color: INK, width: w, linecap: 'round' });
    return g.polyline(pstr(pts)).fill('none').stroke({ color: '#000', width: 18, opacity: 0.001 });
  }

  function rightAngle(g, px, py, u1, u2, s) {
    var p = [[px, py], [px + u1[0] * s, py + u1[1] * s],
             [px + (u1[0] + u2[0]) * s, py + (u1[1] + u2[1]) * s],
             [px + u2[0] * s, py + u2[1] * s]];
    return g.polygon(pstr(p)).fill(GREY).stroke({ color: INK, width: 2 });
  }

  /* ---------------- shared scene pieces ---------------- */
  var dragPanel = null;

  function boat(g, x, y, sc, key) {
    var grp = g.group();
    grp.line(-92, 14, -58, 14).stroke({ color: INK, width: 3, opacity: 0.55 });
    grp.line(62, 16, 92, 16).stroke({ color: INK, width: 3, opacity: 0.55 });
    grp.path('M -42 0 Q -22 -8 0 -8 Q 24 -8 44 0 Q 29 18 0 19 Q -29 18 -42 0 Z')
      .fill('#fff').stroke({ color: INK, width: 3.6, linejoin: 'round' });
    grp.line(-34, 3, 38, 3).stroke({ color: INK, width: 2.6 });
    grp.line(0, 4, 0, -86).stroke({ color: INK, width: 3.6 });
    grp.path('M -1 -84 Q -24 -44 -39 -12 L -1 -12 Z')
      .fill('#fff').stroke({ color: INK, width: 3.4, linejoin: 'round' });
    grp.path('M 2 -78 L 2 -12 L 36 -12 Z')
      .fill('#fff').stroke({ color: INK, width: 3.4, linejoin: 'round' });
    grp.attr('transform', 'translate(' + x + ',' + y + ') scale(' + sc + ')');
    attach(grp, 'The boat — drag it sideways to change its true distance d',
      'The target',
      'The boat is the unknown. Its picture alone carries no distance information: d only appears once a known length in the scene (the eye height h, or the baseline t) is combined with measured angles.');
    grp.on('mousedown', function (e) { dragPanel = key; e.preventDefault(); });
    grp.css('cursor', 'ew-resize');
    return grp;
  }

  function eye(g, x, y, tick, tip, title, body) {
    var c = g.circle(28).center(x, y).fill('#fff').stroke({ color: INK, width: 5 });
    if (tick) g.path('M ' + (x - 6) + ' ' + (y + 1) + ' L ' + x + ' ' + (y + 8) + ' L ' + (x + 6) + ' ' + (y - 2))
      .fill('none').stroke({ color: INK, width: 2.6, linejoin: 'round' });
    attach(c, tip, title, body);
    return c;
  }

  /* ---------------- LEFT PANEL ---------------- */
  function leftDpxFor(d) {
    if (S.trueScale) { var s = Math.min(400 / d, 205 / S.h); return d * s; }
    return 110 + 320 * Math.pow(d / 1200, 0.55);
  }
  function leftHpxFor(d) {
    if (S.trueScale) { var s = Math.min(400 / d, 205 / S.h); return S.h * s; }
    return 55 + 155 * Math.pow((S.h - 2) / 118, 0.6);
  }
  function leftGeom() {
    var d = S.dL, waterY = 285, eyeX = 95;
    var hpx = leftHpxFor(d), dpx = leftDpxFor(d);
    var eyeY = waterY - hpx;
    var hz = Math.max(46, Math.min(waterY - 24, eyeY + 32));
    return { hpx: hpx, dpx: dpx, eyeX: eyeX, eyeY: eyeY, waterY: waterY, hz: hz, xB: eyeX + dpx };
  }

  function drawLeft(g, act) {
    var G = leftGeom(), lw = act ? 3.2 : 2.2;
    var wY = G.waterY, ex = G.eyeX, ey = G.eyeY, hp = G.hpx, xB = G.xB;

    g.rect(PW, PH).fill('#fff');
    g.rect(PW, PH - G.hz).move(0, G.hz).fill(SEA);

    var coast = [[-8, PH + 8], [-8, G.hz - 6], [46, G.hz + 12],
      [94, Math.min(wY - 28, G.hz + 40)], [150, wY - 6], [206, wY + 8],
      [258, wY + 28], [310, wY + 54], [358, wY + 82], [406, PH + 8]];
    g.polygon(pstr(coast)).fill(LAND).stroke({ color: LAND_EDGE, width: 5, linejoin: 'round' });
    g.line(0, G.hz, PW, G.hz).stroke({ color: INK, width: act ? 6 : 4 });

    var bY = wY + 16, rB = Math.min(92, Math.max(44, G.dpx - 34));
    var cliff = [[ex - 86, bY + 6], [ex - 78, wY - 0.12 * hp], [ex - 66, wY - 0.30 * hp],
      [ex - 55, ey + 0.52 * hp], [ex - 45, ey + 0.24 * hp], [ex - 34, ey + 0.45 * hp],
      [ex - 20, ey + 0.13 * hp], [ex - 3, ey - 11], [ex + 13, ey + 0.17 * hp],
      [ex + 27, ey + 0.41 * hp], [ex + 45, wY - 0.29 * hp], [ex + 66, wY - 0.09 * hp],
      [ex + rB, bY], [ex + rB - 32, bY + 11], [ex - 32, bY + 12]];
    g.polygon(pstr(cliff)).fill(CLIFF).stroke({ color: CLIFF_EDGE, width: 7, linejoin: 'round' });
    [[ex - 45, ey + 0.24 * hp], [ex - 3, ey - 11], [ex + 27, ey + 0.41 * hp]].forEach(function (p) {
      g.path('M ' + (p[0] - 7) + ' ' + (p[1] + 2) + ' L ' + p[0] + ' ' + (p[1] - 11) + ' L ' + (p[0] + 7) + ' ' + (p[1] + 2))
        .fill('none').stroke({ color: CLIFF_EDGE, width: 2.6, linecap: 'round' });
    });

    var rayEnd = Math.min(PW - 26, xB + 66);
    g.line(ex, ey, rayEnd, ey).stroke({ color: INK, width: lw, dasharray: '12,8' });
    g.line(ex, ey, xB, wY).stroke({ color: INK, width: lw });
    g.line(ex, ey, ex, wY).stroke({ color: INK, width: lw });
    g.line(ex, wY, xB, wY).stroke({ color: INK, width: lw });
    rightAngle(g, ex, wY, [0, -1], [1, 0], 18);

    attach(hitLine(g, ex + 40, ey, rayEnd, ey),
      'Dashed horizontal line of sight to the horizon — the angle reference',
      'The horizon ray',
      'A flat sea hands the observer a free horizontal reference: the sight line to the horizon. The depression angle α is measured downward from it.');
    attach(hitLine(g, ex, ey + 26, ex, wY),
      'h = known eye height above the water — the baseline of this method',
      'Height is the baseline',
      'The eye height h is the known length. With the right angle at the water plane and the measured angle α it closes the triangle: d = h / tan α. No known length, no distance.');
    attach(hitLine(g, ex + 24, wY, xB - 34, wY),
      'd = the unknown horizontal distance to the boat',
      'The unknown distance',
      'The horizontal leg is what we want. It is never measured directly — it is inferred from h and α, so any error in either propagates straight into d.');

    var aB = Math.atan2(wY - ey, xB - ex);
    var rE = Math.max(46, Math.min(112, 0.32 * G.dpx));
    attach(arcEl(g, ex, ey, rE, 0, aB, act ? 2.8 : 2),
      'α = depression angle actually drawn here: ' + deg(aB).toFixed(1) + '°',
      'The depression angle',
      'α is the angle between the horizon ray and the sight ray to the boat. The number printed beside the arc is the angle really drawn on screen. As the boat recedes α shrinks toward zero, so a small angular error becomes an enormous distance error.');
    var mid = aB / 2;
    T(g, 'α', ex + (rE + 30) * Math.cos(mid), ey + (rE + 30) * Math.sin(mid), 40, { italic: true });
    T(g, deg(aB).toFixed(1) + '°', ex + (rE + 80) * Math.cos(mid), ey + (rE + 80) * Math.sin(mid), 24, { sans: true, color: '#333' });

    var sp = angSpan(Math.PI, Math.atan2(ey - wY, ex - xB));
    var rBo = Math.max(38, Math.min(86, 0.22 * G.dpx));
    attach(arcEl(g, xB, wY, rBo, sp.a1, sp.a2, act ? 2.8 : 2),
      'the same α reappears at the boat (alternate interior angles)',
      'Alternate interior angles',
      'The horizon ray and the water plane are parallel, so the sight line cuts them at equal angles: the angle at the boat equals α. That is what makes the right triangle solvable.');
    T(g, 'α', xB + (rBo + 30) * Math.cos(sp.mid), wY + (rBo + 30) * Math.sin(sp.mid), 40, { italic: true });
    T(g, deg(sp.w).toFixed(1) + '°', xB + (rBo + 78) * Math.cos(sp.mid), wY + (rBo + 78) * Math.sin(sp.mid), 24, { sans: true, color: '#333' });

    T(g, 'h', ex - 34, (ey + wY) / 2, 40, { italic: true });
    T(g, 'd?', ex + 0.44 * G.dpx, wY - 28, 40, { italic: true });

    boat(g, xB, wY, 0.95, 'L');
    eye(g, ex, ey, false, 'Observer, eye height h above the water',
      'The observer', 'The observer measures only angles. Angles alone never give distance — they must be anchored to a known length: here, the height of the eye above the sea.');

    T(g, 'd = h / tan α', PW - 26, 36, 26, { anchor: 'end', italic: true, color: '#222' });
  }

  /* ---------------- RIGHT PANEL ---------------- */
  function rightCalc(t, d) {
    var Ax = 88, Ay = 172, dy = 41;
    var Lx0 = 170 + 250 * Math.pow(d / 1200, 0.55);
    var L0 = Math.sqrt(Lx0 * Lx0 + dy * dy);
    var u = [Lx0 / L0, dy / L0];
    var s = Math.min(L0 / d, 230 / t);
    var L = s * d, Bl = s * t;
    var A = [Ax, Ay], P = [Ax + L * u[0], Ay + L * u[1]];
    var ut = [0.700, 0.714];
    var B = [Ax + Bl * ut[0], Ay + Bl * ut[1]];
    var vBP = nrm([P[0] - B[0] || 1e-6, P[1] - B[1]]);
    var al = ang(ut, u);
    var be = (Bl < 0.5) ? (Math.PI - al) : ang([-ut[0], -ut[1]], vBP);
    var ga = Math.max(1e-5, Math.PI - al - be);
    return { A: A, B: B, P: P, u: u, ut: ut, L: L, Bl: Bl, s: s, al: al, be: be, ga: ga };
  }
  function rightGeom() { return rightCalc(S.t, S.dR); }

  function drawRight(g, act) {
    var R = rightGeom(), lw = act ? 3.2 : 2.2, hz = 150;
    var A = R.A, B = R.B, P = R.P;

    g.rect(PW, PH).fill('#fff');
    g.rect(PW, PH - hz).move(0, hz).fill(SEA);
    var coast = [[-8, PH + 8], [-8, 142], [56, 152], [100, 172], [132, 196], [164, 226],
      [196, 256], [230, 286], [266, 316], [300, 344], [338, PH + 8]];
    g.polygon(pstr(coast)).fill(LAND).stroke({ color: LAND_EDGE, width: 5, linejoin: 'round' });
    g.line(0, hz, PW, hz).stroke({ color: INK, width: act ? 6 : 4 });

    g.line(A[0] - 24, A[1] + 18, A[0] + 26, A[1] + 15).stroke({ color: CLIFF_EDGE, width: 6, linecap: 'round', opacity: 0.8 });
    g.line(B[0] - 24, B[1] + 18, B[0] + 26, B[1] + 15).stroke({ color: CLIFF_EDGE, width: 6, linecap: 'round', opacity: 0.8 });

    g.line(A[0], A[1], B[0], B[1]).stroke({ color: INK, width: lw });
    g.line(A[0], A[1], P[0], P[1]).stroke({ color: INK, width: lw });
    g.line(B[0], B[1], P[0], P[1]).stroke({ color: INK, width: lw });

    if (R.Bl > 74) {
      var pr = (B[0] - A[0]) * R.u[0] + (B[1] - A[1]) * R.u[1];
      var F = [A[0] + R.u[0] * pr, A[1] + R.u[1] * pr];
      g.line(B[0], B[1], F[0], F[1]).stroke({ color: INK, width: 2 });
      rightAngle(g, F[0], F[1], [-R.u[0], -R.u[1]], nrm([B[0] - F[0], B[1] - F[1]]), 15);
    }

    attach(hitLine(g, A[0] + 20 * R.ut[0], A[1] + 20 * R.ut[1], B[0] - 18 * R.ut[0], B[1] - 18 * R.ut[1]),
      't = known separation of the two observers — the baseline',
      'The baseline t',
      'Here the known length is the gap between two observers. This panel is drawn to a single uniform scale, so the printed α and β are exactly the angles of the real triangle and the law of sines returns the slider distance.');
    attach(hitLine(g, A[0] + 44 * R.u[0], A[1] + 44 * R.u[1], P[0] - 44 * R.u[0], P[1] - 44 * R.u[1]),
      'd = distance from the upper observer to the boat (unknown)',
      'The unknown distance',
      'With t known and both angles measured, d = t · sin β / sin(α + β). No height and no horizon are needed — only a baseline and two angles.');

    var aAB = Math.atan2(R.ut[1], R.ut[0]), aAP = Math.atan2(R.u[1], R.u[0]);
    var spA = angSpan(aAP, aAB);
    var rA = Math.max(26, Math.min(62, 0.55 * R.Bl));
    attach(arcEl(g, A[0], A[1], rA, spA.a1, spA.a2, act ? 2.8 : 2),
      'α = ' + deg(R.al).toFixed(1) + '° — angle at the upper observer, read off the drawn rays',
      'Angle α', 'The upper observer measures the angle between the baseline to the partner and the sight ray to the boat. It is computed here from the actual drawn geometry, never from a stored constant.');
    var lrA = Math.max(rA + 34, 1.2 * R.Bl + 26);
    T(g, 'α', A[0] + lrA * Math.cos(spA.mid), A[1] + lrA * Math.sin(spA.mid), 40, { italic: true });
    T(g, deg(R.al).toFixed(1) + '°', A[0] + (lrA + 48) * Math.cos(spA.mid), A[1] + (lrA + 48) * Math.sin(spA.mid), 24, { sans: true, color: '#333' });

    var spB = angSpan(Math.atan2(-R.ut[1], -R.ut[0]), Math.atan2(P[1] - B[1], P[0] - B[0]));
    var rBa = Math.max(26, Math.min(54, 0.5 * R.Bl + 20));
    attach(arcEl(g, B[0], B[1], rBa, spB.a1, spB.a2, act ? 2.8 : 2),
      'β = ' + deg(R.be).toFixed(1) + '° — angle at the lower observer',
      'Angle β', 'The second observer measures its own angle to the same boat. Two angles plus the baseline fix the third vertex of the triangle completely.');
    T(g, 'β', B[0] + (rBa + 32) * Math.cos(spB.mid), B[1] + (rBa + 32) * Math.sin(spB.mid), 40, { italic: true });
    T(g, deg(R.be).toFixed(1) + '°', B[0] + (rBa + 80) * Math.cos(spB.mid), B[1] + (rBa + 80) * Math.sin(spB.mid), 24, { sans: true, color: '#333' });

    var spP = angSpan(Math.atan2(A[1] - P[1], A[0] - P[0]), Math.atan2(B[1] - P[1], B[0] - P[0]));
    attach(arcEl(g, P[0], P[1], 36, spP.a1, spP.a2, act ? 2.8 : 2),
      'γ = ' + deg(R.ga).toFixed(1) + '° — the apex (parallax) angle at the boat',
      'The apex angle γ',
      'γ = 180° − α − β is the angle the baseline subtends at the boat. It is the whole ball game: as γ collapses toward zero the triangle degenerates and the inferred distance becomes wildly sensitive to angular error.');
    var gx = P[0] - 96, gy = P[1] - 82, warnG = R.ga < 2.5 * Math.PI / 180;
    if (gx < 70) { gx = P[0] + 70; gy = P[1] + 70; }
    g.line(gx + 22, gy + 16, P[0] - 26, P[1] - 12).stroke({ color: '#666', width: 1.6 });
    T(g, 'γ', gx, gy, 38, { italic: true, color: warnG ? WARN : INK });
    T(g, deg(R.ga).toFixed(1) + '°', gx + 44, gy + 3, 24, { sans: true, color: warnG ? WARN : '#333' });

    var m = [(A[0] + P[0]) / 2, (A[1] + P[1]) / 2];
    T(g, 'd?', m[0] + 30 * R.u[1], m[1] - 30 * R.u[0], 40, { italic: true });
    var tm = [(A[0] + B[0]) / 2, (A[1] + B[1]) / 2], off = R.Bl < 70 ? 52 : 32;
    T(g, 't', tm[0] - off * R.ut[1], tm[1] + off * R.ut[0], 40, { italic: true });

    boat(g, P[0], P[1], 0.95, 'R');
    eye(g, A[0], A[1], false, 'Upper observer — measures α',
      'Observer A', 'Observer A measures the angle α between the baseline and the boat. Neither observer needs to know a height, and neither needs the horizon.');
    eye(g, B[0], B[1], true, 'Lower observer — measures β',
      'Observer B', 'Observer B measures β to the same boat. The two bearings intersect at exactly one point, and the known baseline converts that intersection into metres.');

    T(g, 'd = t · sin β / sin(α + β)', PW - 26, 36, 26, { anchor: 'end', italic: true, color: '#222' });
  }

  /* ---------------- read-out (side panel, never on canvas) ---------------- */
  function updateReadout() {
    var el = document.getElementById('readout');
    if (!el) return;
    var G = leftGeom();
    var aT = Math.atan(S.h / S.dL), aD = Math.atan2(G.hpx, G.dpx);
    var E = (G.hpx / S.h) / (G.dpx / S.dL);
    var R = rightGeom();
    var dImp = S.t * Math.sin(R.be) / Math.sin(R.al + R.be);

    var h1 = '<b>Left — one observer</b><br>' +
      'h = ' + S.h + ' m &nbsp; d = ' + Math.round(S.dL) + ' m<br>' +
      'α = atan(h / d) = <b>' + deg(aT).toFixed(2) + '°</b><br>' +
      'd = h / tan α = <b>' + Math.round(S.h / Math.tan(aT)) + ' m</b><br>';
    if (S.trueScale) {
      h1 += '<span style="color:#2a7a2a">drawn 1:1 — the arc on screen is the true α (' + deg(aD).toFixed(2) + '°)</span>';
    } else {
      h1 += '<span style="color:#777">arc as drawn: ' + deg(aD).toFixed(1) +
        '° — the sketch stretches the vertical scale ×' + E.toFixed(1) +
        ' so the small true angle stays visible. Tick “true 1:1 scale” to remove the stretch.</span>';
    }
    if (deg(aT) < 1.5) h1 += '<br><span style="color:' + WARN + '">⚠ α &lt; 1.5°: a 0.1° error shifts d by hundreds of metres.</span>';

    var h2 = '<b>Right — two observers</b><br>' +
      't = ' + S.t + ' m &nbsp; d = ' + Math.round(S.dR) + ' m<br>' +
      'α = <b>' + deg(R.al).toFixed(1) + '°</b>, β = <b>' + deg(R.be).toFixed(1) +
      '°</b>, γ = <b>' + deg(R.ga).toFixed(1) + '°</b><br>' +
      'd = t · sin β / sin(α + β) = <b>' + Math.round(dImp) + ' m</b><br>' +
      '<span style="color:#2a7a2a">panel drawn to a single scale — printed angles are the drawn angles ✓</span>';
    if (deg(R.ga) < 2.5) h2 += '<br><span style="color:' + WARN + '">⚠ apex angle γ &lt; 2.5°: baseline far too short for this range — d is barely determined.</span>';

    el.innerHTML = h1 + '<br><br>' + h2;
  }

  /* ---------------- render ---------------- */
  function render() {
    root.clear();
    root.rect(VW, VH).fill('#fff');
    var actL = (S.mode === 'both' || S.mode === 'single');
    var actR = (S.mode === 'both' || S.mode === 'two');

    T(root, 'One observer: height + horizon', OXL + PW / 2, 26, 26,
      { sans: true, bold: true, color: actL ? '#111' : '#999' });
    T(root, 'Two observers: triangulation', OXR + PW / 2, 26, 26,
      { sans: true, bold: true, color: actR ? '#111' : '#999' });

    var gL = root.group().attr('transform', 'translate(' + OXL + ',' + MT + ')');
    gL.clipWith(clipL); drawLeft(gL, actL);
    var gR = root.group().attr('transform', 'translate(' + OXR + ',' + MT + ')');
    gR.clipWith(clipR); drawRight(gR, actR);
    if (!actL) gL.opacity(0.42);
    if (!actR) gR.opacity(0.42);

    root.rect(PW, PH).move(OXL, MT).fill('none').stroke({ color: INK, width: 7 });
    root.rect(PW, PH).move(OXR, MT).fill('none').stroke({ color: INK, width: 7 });
    if (S.mode === 'single') ring(OXL);
    if (S.mode === 'two') ring(OXR);
    updateReadout();
  }
  function ring(ox) {
    root.rect(PW + 16, PH + 16).move(ox - 8, MT - 8).radius(7)
      .fill('none').stroke({ color: ACC, width: 4, opacity: 0.85 });
  }
  window.figRender = render;

  /* ---------------- drag ---------------- */
  function toVB(e) {
    var pt = draw.node.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    var m = draw.node.getScreenCTM();
    if (!m) return { x: 0, y: 0 };
    return pt.matrixTransform(m.inverse());
  }
  function invert(fn, target, lo, hi) {
    for (var i = 0; i < 44; i++) {
      var mid = (lo + hi) / 2;
      if (fn(mid) < target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }
  window.addEventListener('mousemove', function (e) {
    if (!dragPanel) return;
    var p = toVB(e), nd;
    if (dragPanel === 'L') {
      nd = invert(leftDpxFor, p.x - OXL - 95, 50, 1200);
    } else {
      nd = invert(function (dd) { return rightCalc(S.t, dd).P[0]; }, p.x - OXR, 50, 1200);
    }
    nd = Math.max(50, Math.min(1200, Math.round(nd / 10) * 10));
    if (dragPanel === 'L' && nd !== S.dL) { S.dL = nd; figSetSlider('boatDistance', nd); render(); }
    if (dragPanel === 'R' && nd !== S.dR) { S.dR = nd; figSetSlider('boatDistance', nd); render(); }
  });
  window.addEventListener('mouseup', function () { dragPanel = null; });

  render();
  window.__markRendered();
})();

/* ---------------- UI plumbing ---------------- */
function figSetSlider(id, v) {
  var i = document.getElementById(id + 'Input'), o = document.getElementById(id + 'Val');
  if (i) i.value = v;
  if (o) o.value = v;
}
window.figSetSlider = figSetSlider;

function figSyncUI() {
  var m = window.figState.mode;
  var hRow = document.getElementById('hRow'), tRow = document.getElementById('tRow');
  if (hRow) hRow.style.opacity = (m === 'two') ? '0.42' : '1';
  if (tRow) tRow.style.opacity = (m === 'single') ? '0.42' : '1';
}

function update_observerHeight(v) { window.figState.h = v; window.figRender(); }
function update_observerSeparation(v) { window.figState.t = v; window.figRender(); }
function update_boatDistance(v) {
  var S = window.figState;
  if (S.mode === 'both') { S.dL = v; S.dR = v; }
  else if (S.mode === 'single') { S.dL = v; }
  else { S.dR = v; }
  window.figRender();
}
function toggle_activePanel(v) { window.figState.mode = v; figSyncUI(); window.figRender(); }
function toggle_trueScale(on) { window.figState.trueScale = on; window.figRender(); }

/* ---------------- demo steps ---------------- */
var demoSteps = [
  { title: 'The unknown: how far is the boat?',
    narration: 'Both panels show the same sea and the same boat at distance d. The picture alone cannot tell you how far it is — you need one known length somewhere in the scene.',
    state: { activePanel: 'both', observerHeight: 40, observerSeparation: 80, boatDistance: 400 } },
  { title: 'Left panel: height plus horizon',
    narration: 'The known length is the eye height h, and the horizon supplies an exactly horizontal reference. The depression angle α closes the right triangle: d = h / tan α. (The sketch stretches the vertical scale; the side panel prints both the true α and the drawn one.)',
    state: { activePanel: 'single', observerHeight: 40, observerSeparation: 80, boatDistance: 400 } },
  { title: 'Climb the cliff',
    narration: 'Raise the eye and α opens up for the very same boat — the arc widens and the printed degrees grow with it. A high lookout measures a bigger, more reliable angle.',
    state: { activePanel: 'single', observerHeight: 110, observerSeparation: 80, boatDistance: 400 } },
  { title: 'Push the boat out',
    narration: 'Send the boat toward the horizon: α collapses in the left panel while the apex angle γ in the right panel nearly vanishes too. A tiny angular error now becomes a huge distance error.',
    state: { activePanel: 'both', observerHeight: 40, observerSeparation: 80, boatDistance: 1100 } },
  { title: 'Right panel: a baseline of two eyes',
    narration: 'Here the known length is the separation t between two observers. Each reads its own angle, α and β, off the drawn rays, and the law of sines fixes the boat — no horizon, no height needed.',
    state: { activePanel: 'two', observerHeight: 40, observerSeparation: 80, boatDistance: 400 } },
  { title: 'Shrink the baseline',
    narration: 'Bring the observers together and the two sight rays become almost parallel: α + β approaches 180°, the apex angle γ collapses, and d is barely determined. This is exactly the small-baseline problem in stereo vision.',
    state: { activePanel: 'two', observerHeight: 40, observerSeparation: 10, boatDistance: 400 } },
  { title: 'Widen the baseline — compare both',
    narration: 'Separate them fully and γ opens up, pinning the distance down. Side by side the two panels do the same job: a known baseline plus measured angles equals depth, and both degrade as that baseline shrinks relative to d.',
    state: { activePanel: 'both', observerHeight: 40, observerSeparation: 190, boatDistance: 400 } }
];
var demoIdx = 0;

function applyDemoStep(i) {
  demoIdx = (i + demoSteps.length) % demoSteps.length;
  var st = demoSteps[demoIdx], s = st.state, S = window.figState;
  if (s.activePanel) {
    S.mode = s.activePanel;
    var sel = document.getElementById('activePanelInput');
    if (sel) sel.value = s.activePanel;
  }
  if (s.observerHeight !== undefined) { S.h = s.observerHeight; figSetSlider('observerHeight', s.observerHeight); }
  if (s.observerSeparation !== undefined) { S.t = s.observerSeparation; figSetSlider('observerSeparation', s.observerSeparation); }
  if (s.boatDistance !== undefined) { S.dL = s.boatDistance; S.dR = s.boatDistance; figSetSlider('boatDistance', s.boatDistance); }
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (demoIdx + 1) + ' / ' + demoSteps.length;
  figSyncUI();
  window.figRender();
}
function nextStep() { applyDemoStep(demoIdx + 1); }
function prevStep() { applyDemoStep(demoIdx - 1); }

applyDemoStep(0);
// @FIGURE_CODE_END

