// @FIGURE_CODE_BEGIN
(function () {
  var SEA = '#5ff7e0', LAND = '#c2830c', LAND_EDGE = '#8a5407',
      CLIFF = '#7a3c08', CLIFF_EDGE = '#4a2404', GREY = '#bdbdbd',
      INK = '#000', ACC = '#1f7ae0', WARN = '#c00000';

  var PW = 580, PH = 372, PAD = 12, GAP = 30, MT = PAD;
  var OXL = PAD, OXR = PAD + PW + GAP;
  var VW = PAD * 2 + PW * 2 + GAP, VH = PAD * 2 + PH;

  var S = { mode: 'both', h: 40, t: 80, dL: 400, dR: 400, trueScale: false, ann: false };
  window.figState = S;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, VW, VH);
  var clipL = draw.clip().add(draw.rect(PW, PH).move(0, 0));
  var clipR = draw.clip().add(draw.rect(PW, PH).move(0, 0));
  var root = draw.group();

  /* ---------------- helpers ---------------- */
  function pstr(a) { return a.map(function (p) { return (+p[0]).toFixed(2) + ',' + (+p[1]).toFixed(2); }).join(' '); }
  function nrm(v) { var l = Math.sqrt(v[0] * v[0] + v[1] * v[1]) || 1; return [v[0] / l, v[1] / l]; }
  function ang(u, v) { var c = u[0] * v[0] + u[1] * v[1]; c = Math.max(-1, Math.min(1, c)); return Math.acos(c); }
  function deg(r) { return r * 180 / Math.PI; }
  function dist(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1]); }

  function T(g, str, x, y, size, o) {
    o = o || {};
    var t = g.plain(str);
    t.font({
      family: o.sans ? 'Helvetica,Arial,sans-serif' : 'Georgia,"Times New Roman",serif',
      size: size, anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal', weight: o.bold ? 'bold' : 'normal'
    });
    t.fill(o.color || INK);
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (o.hw == null ? 7 : o.hw), 'stroke-linejoin': 'round' });
    return t;
  }

  function attach(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }
  function hitLine(g, x1, y1, x2, y2) {
    return g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 20, opacity: 0.001 });
  }
  function angSpan(a1, a2) {
    var d = a2 - a1;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    return { a1: a1, a2: a1 + d, mid: a1 + d / 2, w: Math.abs(d) };
  }
  function arcEl(g, cx, cy, r, a1, a2, w) {
    var pts = [], n = 40, i, a;
    for (i = 0; i <= n; i++) {
      a = a1 + (a2 - a1) * i / n;
      pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
    }
    g.polyline(pstr(pts)).fill('none').stroke({ color: INK, width: w, linecap: 'round' });
    return g.polyline(pstr(pts)).fill('none').stroke({ color: '#000', width: 18, opacity: 0.001 });
  }
  function rightAngle(g, px, py, u1, u2, s) {
    var p = [[px, py], [px + u1[0] * s, py + u1[1] * s],
             [px + (u1[0] + u2[0]) * s, py + (u1[1] + u2[1]) * s],
             [px + u2[0] * s, py + u2[1] * s]];
    return g.polygon(pstr(p)).fill(GREY).stroke({ color: INK, width: 2 });
  }
  /* Greek label anchored just outside an arc, with a leader only when pushed far. */
  function arcLabel(g, ch, cx, cy, rArc, midAng, extra, size, col) {
    var r = rArc + extra;
    var pos = [cx + r * Math.cos(midAng), cy + r * Math.sin(midAng)];
    if (extra > 46) {
      g.line(cx + (rArc + 4) * Math.cos(midAng), cy + (rArc + 4) * Math.sin(midAng),
             pos[0] - 14 * Math.cos(midAng), pos[1] - 14 * Math.sin(midAng))
        .stroke({ color: '#666', width: 1.4 });
    }
    T(g, ch, pos[0], pos[1], size, { italic: true, color: col || INK });
    return pos;
  }

  /* ---------------- shared scene pieces ---------------- */
  var dragPanel = null;

  function boat(g, x, y, sc, key) {
    var grp = g.group();
    grp.line(-92, 14, -58, 14).stroke({ color: INK, width: 3, opacity: 0.55 });
    grp.line(62, 16, 92, 16).stroke({ color: INK, width: 3, opacity: 0.55 });
    grp.path('M -42 0 Q -22 -8 0 -8 Q 24 -8 44 0 Q 29 18 0 19 Q -29 18 -42 0 Z')
      .fill('#fff').stroke({ color: INK, width: 3.6, linejoin: 'round' });
    grp.line(-34, 3, 38, 3).stroke({ color: INK, width: 2.6 });
    grp.line(0, 4, 0, -86).stroke({ color: INK, width: 3.6 });
    grp.path('M -1 -84 Q -24 -44 -39 -12 L -1 -12 Z')
      .fill('#fff').stroke({ color: INK, width: 3.4, linejoin: 'round' });
    grp.path('M 2 -78 L 2 -12 L 36 -12 Z')
      .fill('#fff').stroke({ color: INK, width: 3.4, linejoin: 'round' });
    grp.attr('transform', 'translate(' + x + ',' + y + ') scale(' + sc + ')');
    attach(grp, 'The boat — drag it sideways to change its true distance d',
      'The target',
      'The boat is the unknown. Its picture alone carries no distance information: d only appears once a known length in the scene — the eye height h, or the baseline t — is combined with measured angles.');
    grp.on('mousedown', function (e) { dragPanel = key; e.preventDefault(); });
    grp.css('cursor', 'ew-resize');
    return grp;
  }

  function eye(g, x, y, tick, tip, title, body) {
    var c = g.circle(30).center(x, y).fill('#fff').stroke({ color: INK, width: 5 });
    if (tick) g.path('M ' + (x - 7) + ' ' + (y + 1) + ' L ' + x + ' ' + (y + 9) + ' L ' + (x + 7) + ' ' + (y - 3))
      .fill('none').stroke({ color: INK, width: 2.8, linejoin: 'round' });
    attach(c, tip, title, body);
    return c;
  }

  /* ---------------- LEFT PANEL ---------------- */
  function leftScale() { return Math.min(380 / S.dL, 215 / S.h); }
  function leftDpxFor(d) {
    if (S.trueScale) return d * Math.min(380 / d, 215 / S.h);
    return 190 + 215 * Math.pow(d / 1200, 0.55);
  }
  function leftHpx() {
    var hp = S.trueScale ? S.h * leftScale() : 58 + 150 * Math.pow((S.h - 2) / 118, 0.6);
    return Math.max(26, Math.min(232, hp));
  }
  function leftGeom() {
    var waterY = 292, eyeX = 96;
    var hp = leftHpx(), dpx = leftDpxFor(S.dL);
    var eyeY = waterY - hp;
    var hz = Math.max(52, Math.min(waterY - 48, eyeY + 36));
    var ur = nrm([1, -0.135]);
    var P = [eyeX + dpx * ur[0], waterY + dpx * ur[1]];
    return { hpx: hp, dpx: dpx, eyeX: eyeX, eyeY: eyeY, waterY: waterY, hz: hz, ur: ur, P: P };
  }

  function drawLeft(g, act, ann) {
    var G = leftGeom(), lw = act ? 2.8 : 2.0;
    var wY = G.waterY, ex = G.eyeX, ey = G.eyeY, hp = G.hpx, hz = G.hz, P = G.P, ur = G.ur;

    g.rect(PW, PH).fill('#fff');
    g.rect(PW, PH - hz).move(0, hz).fill(SEA);

    var coast = [[-8, PH + 8], [-8, hz - 2], [46, hz + 14], [94, Math.min(wY - 26, hz + 42)],
      [150, wY - 4], [206, wY + 10], [258, wY + 30], [310, wY + 56], [358, wY + 84], [406, PH + 8]];
    g.polygon(pstr(coast)).fill(LAND).stroke({ color: LAND_EDGE, width: 5, linejoin: 'round' });
    g.line(0, hz, PW, hz).stroke({ color: INK, width: act ? 5 : 4 });

